insert into public.cpl_memory (slug,kind,title,summary,tags,status,source,verified_by,verified_at,author,event_date) values
('d-routine-leaves-plain-handoff-number-s727','decision','The routine leaves a plain session''s handoff number free','S727 conductor: Sam''s plain session S726 merged #3802, #3805 and #3806 before the 06:12Z firing and had not written handoff 727. The routine took S727, the next free number, and wrote handoff 728, leaving 727 to S726 (d-routine-takes-next-free-number-s713). A routine firing follows 728; a plain session follows the handoff its plain sessions write.',array['conductor','routine','handoffs','numbering'],'proposed','docs/session_728_handoff.md',null,null,'SkyTropicbird (S727)','2026-11-25'),
('d-subject-codes-test-person-filing-s727','decision','The subject-codes test accepts a code a person''s filing settles','S727 conductor: tests/statewide_subject_codes_test.py check (5) failed every PR from d4a7899a, since the daily build reads LAWEN as settled by a person''s statewide filing (CRIM), which outranks the named-code rule the check pinned. The check now accepts a code a person''s filing settles; fixed on the display PR #3808 (46a3d804), merged as 0b13c85c.',array['tests','subjects','ci','conductor'],'proposed','#3808',null,null,'SkyTropicbird (S727)','2026-11-25'),
('d-heading-not-in-text-cap-s727','decision','heading_not_in_text caps its course list at 50','S727 conductor, on College of the Canyons''s round 1: before 43388''s insert, the new kind heading_not_in_text (the page prints a requirements list but not the program''s own heading) caps the record''s course-list confidence at 50, since 43388''s list cannot be told from its page''s other lists. Plan s727a applied by migrate 45570064450.',array['program-requirements','named-gaps','college-of-the-canyons','confidence'],'proposed','#3812 (plan s727a)',null,null,'SkyTropicbird (S727)','2026-11-25'),
('d-sbcc-08565-no-units-read-s727','decision','Santa Barbara City 08565 takes no_units_read','S727 conductor, on Santa Barbara City''s round 1: 08565 is filed under no_units_read, the kind its record rules name, in place of pool_figure_not_read; gap_noted now refuses a row the record rules (NG.RECORD_RULES) name under another kind, with a boundary and a test. Plan s727d, 12 rows, applied by migrate 45573614115.',array['program-requirements','santa-barbara-city','named-gaps'],'proposed','claude/s727-piles-sbcc (plan s727d)',null,null,'SkyTropicbird (S727)','2026-11-25'),
('d-sbcc-05934-keeps-hold-s727','decision','Santa Barbara City 05934 keeps S714''s hold','S727 conductor, on Santa Barbara City''s round 1: 05934 leaves plan s727d and keeps S714''s hold, since its ENVS 115 would rest on its note alone. The capture fix it waits on is measured: find_codes found 0 of 97 first codes of a slash cross-listing and 93 of 93 second codes (f-find-codes-misses-slash-first-code-s727).',array['program-requirements','santa-barbara-city','held','capture'],'proposed','claude/s727-piles-sbcc (plan s727d)',null,null,'SkyTropicbird (S727)','2026-11-25'),
('d-west-valley-no-blind-rerun-s727','decision','West Valley''s empty load goes to a follow-up, never a rerun','S727 conductor: West Valley''s read 45574056664 (06276, 32021) filed only capture_preview.json, and its load 45575119022 inserted nothing. A follow-up finds the cause first; neither the read nor the load is rerun blind (d-rccd-pilot-no-blind-force-s671).',array['program-requirements','west-valley','lever','reads'],'proposed','#3811',null,null,'SkyTropicbird (S727)','2026-11-25'),
('d-loads-beside-applies-disjoint-s727','decision','One-college loads ran beside applies on disjoint rows','S727 conductor: Southwestern''s load 45574052184 and West Valley''s load 45575119022 ran beside the applies of plans s727d (Santa Barbara City, migrate 45573614115) and s727v (Antelope Valley, 45575092684), each at another college, on disjoint rows of program_requirement_records: a recorded departure from one write per table at a time.',array['conductor','rule-10','concurrency','program-requirements'],'proposed','docs/session_728_handoff.md',null,null,'SkyTropicbird (S727)','2026-11-25'),
('d-workers-dispatch-loads-in-words-s727','decision','Workers dispatched loads on two branches, in words','S727 conductor: to save its own context, the conductor lifted the workers'' no-dispatch limit in words for loads, rereads and js-tests runs on #3810''s (claude/s727-elumen) and #3811''s (claude/s727-lever) branches. Applies stayed the conductor''s (d-conductor-owns-applies-s720).',array['conductor','workers','dispatch','context'],'proposed','docs/session_728_handoff.md',null,null,'SkyTropicbird (S727)','2026-11-25'),
('d-no-new-workers-after-0757z-s727','decision','No new workers after 07:57Z','S727 conductor: with spend at about $165 at 07:57Z against the run''s aim of about $250, the run started no new worker and landed what was in flight: #3810, #3811, Butte''s reconcile, the records held for a person and the second land PR.',array['conductor','spend','collection'],'proposed','docs/session_728_handoff.md',null,null,'SkyTropicbird (S727)','2026-11-25'),
('p-own-page-guard-reads-read-pages-s727','pitfall','An own-page guard reads the pages the records were read from','S727: American River''s own-page guard took capture.json''s shared_pages, which run 45353541681 built from the re-paginated 2026-27 file, where every record sits on another page (07206 p.429 to 437). Key the guard on sources.json''s source.url and each record''s source_url. 12238, read from p.429 with 07206, holds.',array['program-requirements','guards','american-river','pitfall'],'proposed','#3812 (plan s727b)',null,null,'SkyTropicbird (S727)','2026-11-25'),
('p-insert-rollback-leaves-touched-row-s727','pitfall','An insert''s rollback leaves a row a verdict touched','S727: College of the Canyons''s rollback deleted the inserted 43388, and a verdict on it would refuse the delete through its foreign key. An insert''s rollback leaves a row a verdict touched and lists it, and its delete takes its own expect line. Round 1 caught it before the apply (plan s727a).',array['rule-10','rollback','program-requirements','pitfall'],'proposed','#3812 (plan s727a)',null,null,'SkyTropicbird (S727)','2026-11-25'),
('p-reader-fix-scoped-to-its-road-s727','pitfall','A reader fix is scoped to the catalog road it was aimed at','S727: #3810''s eLumen fix (label_score reads the award from the heading) moved binds on the Acalog and curriQunet roads: El Camino''s heading ''Marketing, AS'' took certificate 19861''s award, and ten certificates read no page. It now applies on elumenapp.com alone; a check over 13,939 other-road filed pages reads 18,377 labels, 0 changed.',array['program-requirements','reader','elumen','pitfall'],'proposed','#3810; docs/kb-notes/methodology-a-reader-fix-moves-rows-it-was-not-aimed-at.md',null,null,'SkyTropicbird (S727)','2026-11-25'),
('p-keep-only-trusts-base-s727','pitfall','Keep-only refuses a base that is not an earlier run''s','S727: Butte''s keep-only restored every record beside the nine to the --base it was given, so the run''s own commit as base would restore nothing. It now refuses unless all nine are kept, each base record holds its line''s figure from an earlier run, every restored file is free of the run and no other record carries it.',array['program-requirements','reconcile','butte','pitfall'],'proposed','claude/s727-butte (745f6940)',null,null,'SkyTropicbird (S727)','2026-11-25'),
('f-find-codes-misses-slash-first-code-s727','fact','find_codes misses a slash cross-listing''s first code','S727: the capture''s find_codes never reads the first code of a slash cross-listing such as ENVS/HIST 112: at Santa Barbara City it found 0 of 97 first codes and 93 of 93 second codes (slash_recall). Santa Barbara City 05934 waits on the fix, a capture change for the follow-up.',array['program-requirements','capture','santa-barbara-city','course-codes'],'proposed','claude/s727-piles-sbcc (plan s727d)',null,null,'SkyTropicbird (S727)','2026-11-25'),
('f-census-ignores-college-named-gaps-s727','fact','The census ignores a college''s own named-gap files','S727: the harvest gap census does not read the named gaps a college''s own file holds for programs with no record, so 14 programs with filed named gaps come back on its lists. Reading those files is the follow-up''s.',array['program-requirements','census','named-gaps'],'proposed','docs/session_728_handoff.md',null,null,'SkyTropicbird (S727)','2026-11-25'),
('f-noted-total-cut-off-needs-recall-s727','fact','noted_total_cut_off fires on 664 failing records','S727: the new named-gap kind noted_total_cut_off, filed for American River 20130 alone (plan s727b), fires on 664 failing records statewide. It needs a self-recall against hand readings before it files anywhere else.',array['program-requirements','named-gaps','self-recall'],'proposed','#3812 (plan s727b)',null,null,'SkyTropicbird (S727)','2026-11-25'),
('f-occ-08626-wrong-page-s727','fact','Orange Coast 08626 is filed from a sister program''s page','S727: Orange Coast 08626, the Powerplant A.S., is filed from the Airframe & Powerplant A.S. page (run 43136182950), with coverage 1.0, since that page prints its AMTA courses. A later lane-1 run gives it its own page or names its gap.',array['program-requirements','orange-coast','reader','own-page'],'proposed','#3811',null,null,'SkyTropicbird (S727)','2026-11-25'),
('f-heading-passes-successor-page-s727','fact','A title heading check alone passes a successor''s page','S727: Orange Coast 32235''s Mathematics AS-T title matches its department''s one transfer degree page, ''Mathematics 2.0'', which prints Control Number 46863. A title heading check alone passes it; the page''s Control Number tells them apart, and 32235 is a named gap, successor_printed.',array['program-requirements','orange-coast','reader','named-gaps'],'proposed','#3811',null,null,'SkyTropicbird (S727)','2026-11-25'),
('f-mission-binds-move-s727','fact','Mission College''s binds move at its next capture','S727: #3810''s eLumen reading moves binds at three colleges and nowhere else: Antelope Valley, College of the Redwoods and Mission College, 8 at Mission. Mission''s move lands at its next capture, after #3810 is on main.',array['program-requirements','elumen','mission','reader'],'proposed','#3810',null,null,'SkyTropicbird (S727)','2026-11-25'),
('f-cuyamaca-18635-wording-rule-s727','fact','Cuyamaca 18635 waits on a wording rule','S727: the pooled plan s727p held Cuyamaca 18635: the reading reads the major''s 18, and the degree adds to 52 against the printed 60. Its note says the page prints no electives line, and a Cuyamaca reconcile wording rule may pass it, so it is not gap-filed (p-gap-filing-leaves-census-lever-s721).',array['program-requirements','cuyamaca','pooled','held'],'proposed','#3812 (plan s727p)',null,null,'SkyTropicbird (S727)','2026-11-25'),
('f-porterville-cuyamaca-real-pools-refused-s727','fact','The pooled reading refuses five real pools','S727: the pooled reading refuses five records whose pages print a real pool: Porterville 06773 and 30235, Cuyamaca 18634, 18636 and 18637. They stay as filed until the reading takes them; the pooled reading''s next.',array['program-requirements','pooled','porterville','cuyamaca'],'proposed','#3812 (plan s727p)',null,null,'SkyTropicbird (S727)','2026-11-25'),
('m-collection-s727','milestone','S727''s collection: 69 records live by 09:40Z','S727 (2026-11-25): 69 records collected and live: pooled 11 to passing; piles Shasta 4, American River 12, Canyons 7, Santa Barbara City 12; persons 5; AVC 43028; 5 on own pages (#3811 loads); eLumen 3 new and 9 reread. 18 named gaps, no record. Census 15,551 pass, 4,227 without. Paid reads about $1.41.',array['program-requirements','collection','milestone'],'proposed','#3808; #3812; #3811; docs/session_728_handoff.md',null,null,'SkyTropicbird (S727)','2026-11-25')
insert into public.cpl_memory_log (memory_id, actor, action, note, after)
